// ============================================
// CALCULATE KEYWORD WEIGHTS
// ============================================
// Transform MongoDB aggregation results into Redis ZADD commands

const items = $input.all();
const domainWeights = {};

for (const item of items) {
  const data = item.json;

  // Extract domain and token from _id
  const domain = data._id?.domain;
  const token = data._id?.token;

  if (!domain || !token) continue;

  // Calculate weight: min(10, count * avg_confidence)
  // This caps weights at 10 to prevent runaway values
  const weight = Math.min(10, data.count * (data.avg_confidence || 0.5));

  // Group by domain
  if (!domainWeights[domain]) {
    domainWeights[domain] = [];
  }

  domainWeights[domain].push({
    token: token,
    weight: Math.round(weight * 100) / 100,  // Round to 2 decimals
    count: data.count,
    avg_confidence: data.avg_confidence
  });
}

// Convert to array for output
const results = [];
for (const [domain, keywords] of Object.entries(domainWeights)) {
  results.push({
    json: {
      domain: domain,
      keywords: keywords,
      total_keywords: keywords.length
    }
  });
}

return results.length > 0 ? results : [{ json: { domain: 'none', keywords: [], total_keywords: 0 } }];

// ============================================
// UPDATE REDIS ZSET FOR EACH DOMAIN
// ============================================

const domain = $json.domain;
const keywords = $json.keywords || [];

if (domain === 'none' || keywords.length === 0) {
  return [{ json: { status: 'skipped', domain: domain, reason: 'no keywords' } }];
}

// Build ZADD arguments: [score1, member1, score2, member2, ...]
const zaddArgs = [];
for (const kw of keywords) {
  zaddArgs.push(kw.weight);
  zaddArgs.push(kw.token);
}

return [{
  json: {
    domain: domain,
    redis_key: `keywords:${domain}:triggers`,
    zadd_args: zaddArgs,
    total_keywords: keywords.length
  }
}];

// ============================================
// SUMMARY LOG
// ============================================

const items = $input.all();
let totalDomains = 0;
let totalKeywords = 0;

for (const item of items) {
  if (item.json.total_keywords) {
    totalDomains++;
    totalKeywords += item.json.total_keywords;
  }
}

return [{
  json: {
    status: 'completed',
    timestamp: new Date().toISOString(),
    domains_updated: totalDomains,
    total_keywords_synced: totalKeywords
  }
}];
